-- Bổ sung câu hỏi thường gặp (bọc răng sứ, trám răng, Implant) cho trang /hoi-dap.
-- Câu trả lời viết riêng, trung tính; cần bác sĩ duyệt trước khi chạy migration vì sẽ hiển thị ngay trên website.
INSERT INTO faq_items (question, answer, sort_order)
SELECT v.question, v.answer, (SELECT COALESCE(MAX(sort_order), -1) FROM faq_items) + v.n
FROM (VALUES
  (1, 'Bao nhiêu tuổi thì bọc răng sứ được?', 'Bọc răng sứ thường được cân nhắc khi răng vĩnh viễn đã mọc đủ và ổn định, thông thường từ khoảng 16–18 tuổi trở lên. Với trẻ nhỏ và thiếu niên, bác sĩ thường ưu tiên các giải pháp bảo tồn răng thật. Độ tuổi phù hợp cụ thể phụ thuộc vào tình trạng răng, nướu và sẽ được xác định sau khi thăm khám.'),
  (2, 'Đã bọc răng sứ rồi có còn bị sâu răng nữa không?', 'Có thể. Mão sứ không bị sâu, nhưng phần răng thật bên trong, đặc biệt ở vùng viền sát nướu, vẫn có thể bị sâu nếu vệ sinh chưa kỹ hoặc viền sứ không khít. Bạn nên đánh răng đúng cách, dùng chỉ nha khoa và tái khám định kỳ khoảng 6 tháng một lần để phát hiện sớm.'),
  (3, 'Răng sứ có bền bằng răng thật không?', 'Răng sứ có độ cứng tốt và chịu lực nhai ổn định, nhưng không thể tự phục hồi như răng thật và có thể mẻ, nứt nếu cắn vật quá cứng hoặc nghiến răng. Độ bền phụ thuộc vào loại sứ, tay nghề, khớp cắn và cách chăm sóc. Bạn nên hỏi rõ điều kiện bảo hành bằng văn bản trước khi thực hiện.'),
  (4, 'Bọc răng sứ có đau không?', 'Quá trình mài răng và lấy dấu thường được thực hiện với gây tê tại chỗ nên bạn ít cảm thấy đau. Sau khi hết tê, một số người bị ê buốt nhẹ trong vài ngày, mức độ khác nhau tùy cơ địa. Nếu ê buốt hoặc đau kéo dài, bạn nên quay lại để bác sĩ kiểm tra.'),
  (5, 'Tác hại của trám răng sai cách là gì?', 'Miếng trám không khít hoặc dư, thiếu có thể gây sâu răng tái phát dưới miếng trám, ê buốt, đau khi nhai, kẹt thức ăn, viêm nướu hoặc lệch khớp cắn. Trường hợp nặng, vi khuẩn xâm nhập có thể gây viêm tủy và phải điều trị phức tạp hơn. Vì vậy nên chọn nơi thăm khám, xử lý sâu răng triệt để trước khi trám.'),
  (6, 'Trám răng và hàn răng khác nhau như thế nào?', 'Hai cách gọi này thường chỉ cùng một kỹ thuật: dùng vật liệu chuyên dụng để phục hồi răng bị sâu, mẻ hoặc sứt. "Trám" được dùng phổ biến ở miền Nam, "hàn" ở miền Bắc. Sự khác biệt thực tế nằm ở loại vật liệu (như composite, GIC) và kỹ thuật bác sĩ chọn cho từng trường hợp.'),
  (7, 'Bao lâu thì nên trám răng lại?', 'Không có mốc cố định cho mọi người. Miếng trám có thể dùng được nhiều năm, nhưng sẽ hao mòn theo thời gian tùy vật liệu, vị trí và thói quen ăn nhai. Bạn nên kiểm tra định kỳ và đến khám sớm nếu thấy ê buốt, miếng trám bị mẻ, bong, đổi màu hoặc kẹt thức ăn ở vị trí đã trám.'),
  (8, 'Trồng răng Implant có nhược điểm gì không?', 'Implant thường có chi phí cao hơn một số giải pháp khác, thời gian điều trị kéo dài do cần chờ trụ tích hợp với xương, và là thủ thuật can thiệp nhỏ nên có nguy cơ biến chứng như nhiễm trùng hoặc trụ không tích hợp tốt, dù không phổ biến. Một số tình trạng sức khỏe chưa kiểm soát hoặc thói quen hút thuốc có thể ảnh hưởng kết quả. Bác sĩ sẽ đánh giá mức độ phù hợp cho bạn.'),
  (9, 'Khi nào cần nâng xoang hoặc ghép xương trước khi trồng Implant?', 'Ghép xương thường được cân nhắc khi xương hàm thiếu chiều cao hoặc độ dày để giữ trụ, thường gặp khi mất răng lâu năm hoặc bị tiêu xương do viêm nha chu. Nâng xoang có thể cần khi trồng răng hàm trên mà đáy xoang quá gần vị trí đặt trụ. Bác sĩ sẽ dựa trên phim chụp để quyết định có cần can thiệp này hay không.')
) AS v(n, question, answer)
WHERE NOT EXISTS (SELECT 1 FROM faq_items f WHERE f.question = v.question);
